// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  FlatList,
  ScrollView,
  Modal

} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Buttons from '../../../Component/Button';
import TextInput from '../../../Component/TextInput';
import { Metrics, Scale } from '../../../utils/size';
import { Routers } from '../../../utils/Routers';
import Toolbar from '../../../Component/Toolbar';
import { getData, removeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import Account from './Account';
// import TreeView from 'react-native-treeview'
// import SortableTree from 'react-sortable-tree';
// import { Root } from 'react-native-tree-schema';
import TreeView from 'react-native-final-tree-view'
import { JSONAxioGet, JSONAxioPost } from '../../../utils/services/JsonService';
import { getURLHub, postURL } from '../../../utils/services/API';
import Loading from '../../../Component/loading';
import PopUp from '../../../Component/popUp';

const MyReferal = ({ route, navigation }) => {
  let [switchAccount, setswitchAccount] = useState(false);
  let [card, setCard] = useState(false);
  let [modalData, setModalData] = useState(false);
  let [modalUpgrade, setModalUpgrade] = useState(false);
  let [loading, setLoading] = useState(false);
  let [token, setToken] = useState(0);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);

  let [upgradeHub, setUpgradeHub] = useState(false);
  let [dataCoint, setDataCoint] = useState({ focoCoint: "0", focoPoint: "0", saldo: "0", totalReferal: 0 });
  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      setswitchAccount(res ? true : false);
    });

    getData(Constants.SESSION_USER_PROFILE).then(res => {
      setToken(res.result.token)
      getListCircle(res.result.token);
    })
    
  }, []);

  let [listItem, setlistItem] = useState([]);
  let [popUpCircle, setPopUpCircle] = useState([]);

  const onPressItem = (item) => {
    switch (item.flag) {
      case 'change_profile':
        navigation.navigate(Routers.EDIT_PROFILE_SCREEN, {})
        break;
      case 'change_email':
        navigation.navigate(Routers.EDIT_EMAIL_SCREEN, {})
        break;
      case 'change_passsword':
        navigation.navigate(Routers.EDIT_PASSWORD_SCREEN, {})
        break;


    }

  }


  const goBack = (item) => {
    navigation.goBack()
  }

  const onPresButton = () =>{
    setModalData(false)
  }

  const onPresShowUpgradeHub = () =>{
    setModalData(false)
  }

  const onPresUpgradeHub = () =>{
    setModalUpgrade(false)
    setLoading(true);
    var param ={
    }
    JSONAxioPost(postURL('api_ajukan_hub', null), param, token)
    .then(respone => {
      const response = respone?.data;

      setLoading(false);
      if (response?.statusCode == 1) {
        navigation.navigate(Routers.SUCCESS_SCREEN, {title: 'Pengajuan Diproses', desc: response?.message, titleButton:'Dashboard'})
      } else {
        cekError(response.statusCode,  response.message);

      }
    })
    .catch(error => {
      setLoading(false);
      cekError(2,  null);

    });
  }

  const getIndicator = (isExpanded, hasChildrenNodes) => {
    if (!hasChildrenNodes) {
      return '-'
    } else if (isExpanded) {
      return '▼'
    } else {
      return '▶'
    }
  }

  const showPopUp = (item) => {

    setPopUpCircle(item)
    setModalData(true)
  }
  
  const getListCircle = (token) => {
    setLoading(true);
    JSONAxioGet(getURLHub("api_circle_saya", null), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        if (response.statusCode == 1) {
          setlistItem(Array.isArray(response.result) ? response.result : []);
          setCard(response.card)
          setUpgradeHub(response.upgrade);
        } else {

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack" }] });
        });
      });
    }

  }

  return (
    <View style={{ flex: 1, backgroundColor: Colors.white }}>

      <Toolbar
        switchAccount={switchAccount}
        onPress={goBack}
        title={'Circle Saya'} />

      <Account
        dataCoint={card}
        switchAccount={switchAccount}
        navigation={navigation} />

     {upgradeHub && <Buttons
        onPress={() => setModalUpgrade(true)}
        style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), backgroundColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
        styleTitle={{ fontSize: Scale(12) }}
        title={"UPGRADE MENJADI HUB"} />}

      {listItem.length > 0 && <ScrollView>

        <View style={{
          flex: 1
        }}>

        <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}>
          <View style={{ flex: 1, margin: Scale(16) }}>

            <TreeView
              data={listItem} // defined above
              renderNode={({ node, level, isExpanded, hasChildrenNodes }) => {
                return (
                  <View style={[{
                    marginLeft: 25 * level, marginRight:Scale(20), width: Metrics.screenWidth - Scale(60), flexDirection: 'row', justifyContent: 'center', alignItems: 'center', borderBottomWidth: Scale(0.5), borderBottomColor: Colors.gray8a
                  }]}>

                    <View style={{ flex: 0.1 }}>
                      <Text
                        style={[styles.text40012, { width: Scale(20),fontSize: Scale(18), color : switchAccount ? Colors.primaryColorHub : Colors.primaryColor}]}
                      >
                        {getIndicator(isExpanded, hasChildrenNodes)}
                      </Text>
                    </View>

                    <View style={{ flex: 1, paddingLeft: Scale(8) }}>
                      <Text
                        style={styles.text40012}
                      >
                        {node.name}
                      </Text>

                      <Text
                        style={styles.text40012}
                      >
                        {node.durasiPembelian}
                      </Text>
                    </View>

                    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'flex-end' }}>
                      <TouchableOpacity
                        onPress={() => showPopUp(node)}>
                        <View style={{ height: Scale(40), marginHorizontal: Scale(16), marginVertical: Scale(16) }}>
                          <Text
                            style={[styles.text40012, { color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor  }]}
                          >
                            {"Lihat Detil"}
                          </Text>

                          <Text
                            style={[styles.text40012, { color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }]}
                          >
                            {node.totalPembelian}
                          </Text>
                        </View>
                      </TouchableOpacity>
                    </View>

                  </View>
                )
              }}
            />

          </View>
          </ScrollView>

        </View>
      </ScrollView >}

      {listItem.length == 0 &&
        <View style={{ height: Metrics.screenHeight / 2, justifyContent: 'center', alignItems: 'center' }}>

          <Image
            style={{ height: Scale(150), width: Scale(150) }}
            source={getIcon('img_oops')}
            resizeMode='contain' />

          <Text style={{ fontSize: Scale(18), textAlign: 'center' }}>Anda belum memiliki Circle saat ini</Text>

        </View>}


      <Modal
            style ={{backgroundColor: Colors.blackTrancparent, justifyContent: 'center', alignItems: 'center' }}
            animationType="slide"
            transparent={true}
            visible={modalData}
            onRequestClose= {() => {setModalData(false)}}>

        <View style={{ height: Metrics.screenHeight, width: Metrics.screenWidth, backgroundColor: Colors.blackTrancparent }}>
         

          <View style={{
            flex: 1,
            marginTop: Metrics.screenHeight/2.5,
            backgroundColor: Colors.white
          }}>
              <Account
                dataCoint={popUpCircle}
                switchAccount={switchAccount}
                navigation={navigation} />

            <Buttons
              onPress={() => onPresButton()}
              style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), backgroundColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
              styleTitle={{ fontSize: Scale(12) }}
              title={"Tutup"} />

          </View>

        
          
        </View>
        </Modal>

        <Modal
            style ={{backgroundColor: Colors.blackTrancparent, justifyContent: 'center', alignItems: 'center' }}
            animationType="slide"
            transparent={true}
            visible={modalUpgrade}
            >

        <View style={{ height: Metrics.screenHeight, width: Metrics.screenWidth, backgroundColor: Colors.blackTrancparent }}>
         

          <View style={{
            flex: 1,
            marginTop: Metrics.screenHeight/2.5,
            backgroundColor: Colors.white
          }}>

            <Text
              style={[styles.text40012, { color: Colors.black, textAlign:'center', marginTop: Scale(16), fontSize: Scale(14), fontWeight:'bold'}]}
            >
              {"Upgrage Menjadi HUB"}
            </Text>

            <Text
              style={[styles.text40012, { color: Colors.black, marginTop: Scale(16), fontSize: Scale(12), marginHorizontal: Scale(16)}]}
            >
              {"Dengan klik tombol Ajukan , Data anda akan di cek oleh admin untuk persetujuan upgrade menjadi HUB . \n\nAnda bisa membatalkan proses pengajuan upgrade menjadi HUB dengan klik tombol Batal "}
            </Text>

            <View style={{ marginVertical: Scale(16), marginHorizontal: Scale(16), flexDirection: 'row' }}>


              {<Image
                style={{ height: Scale(20), width: Scale(20), tintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                source={getIcon('ic_success')}
                resizeMode='contain' />}

              <Text
                style={[styles.text40012, { color: Colors.black, fontSize: Scale(12), marginHorizontal: Scale(16) }]}
              >
                {"Periksa kembali data anda sebelum proses pengajuan HUB"}
              </Text>
            </View>

            <View style={{ marginVertical: Scale(16), marginHorizontal: Scale(16), flexDirection: 'row' }}>


              {<Image
                style={{ height: Scale(20), width: Scale(20), tintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                source={getIcon('ic_24')}
                resizeMode='contain' />}

              <Text
                style={[styles.text40012, { color: Colors.black, fontSize: Scale(12), marginHorizontal: Scale(16) }]}
              >
                {"Jika memenuhi syarat dan ketentuan, persetujuan akan di proses maximal 24 jam kerja "}
              </Text>
            </View>
            

            <View style={{ flexDirection: 'row' }}>


              <View style={{ flex: 1 }}>
                <Buttons
                  onPress={() => setModalUpgrade(false)}
                  style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), borderColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor, borderWidth: Scale(1), backgroundColor: Colors.white }}
                  styleTitle={{ fontSize: Scale(12), color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                  title={"Batal"} />
              </View>

              <View style={{ flex: 1 }}>
                <Buttons
                  onPress={() => onPresUpgradeHub()}
                  style={{ height: Scale(50), margin: Scale(16), marginTop: Scale(10), borderRadius: Scale(8), backgroundColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                  styleTitle={{ fontSize: Scale(12) }}
                  title={"Ajukan"} />
              </View>



            </View>
          </View>

        
          
        </View>
        </Modal>



        <Loading
        visible={loading} />

      <PopUp
        visible={warning}
        onPressButton={() => { actionButton() }}
        title={contentWarning?.title}
        desc={contentWarning?.desc}
        titleButton={contentWarning?.titleButton} />

    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
});
export default MyReferal;