// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  FlatList
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import { Metrics, Scale } from '../../../utils/size';
import TextInput from '../../../Component/TextInput';
import { getData, removeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import ItemOrder from './ItemOrder';
import { Routers } from '../../../utils/Routers';
import ModalStatusReadyToSend from '../../../Component/ModalStatusReadyToSend';
import ModalConformationSendHub from '../../../Component/ModalConformationSendHub';
import { JSONAxioGet, JSONAxioGetNew, JSONAxioPost } from '../../../utils/services/JsonService';
import { getURLHub, postURL } from '../../../utils/services/API';
import PopUp from '../../../Component/popUp';
import Loading from '../../../Component/loading';
import TabLayout from '../../HomeScreen/HubScreen/TabLayout';
import ModalTracking from '../../../Component/ModalTracking';
import Buttons from '../../../Component/Button';
import ModalSetoranCod from '../../../Component/ModalSetoranCod';

const RiwayatCod = ({ route, navigation }) => {
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const [selectItem, setSelectItem] = useState(null);
  let [search, setSearch] = useState(null);
  let [titleType, setTitleType] = useState("Terbaru");
  
  let [loading, setLoading] = useState(false);
  let [loadingFull, setLoadingFull] = useState(false);
  let [showStatus, setShowStatus] = useState(false);
  let [title, setTitle] = useState("Terbaru");
  const [tabFlag, setTabFlag] = useState('1');
  let [switchAccount, setswitchAccount] = useState(false);
  let [warning, setWarning] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
  let [token, setToken] = useState(null);
  let [detil, setDetil] = useState(null);
  let [items, setItem] = useState(null);
  let [arraySelection, setArraySelection] = useState([]);
  const [showModalStatus, setShowModalStatus] = useState(false);

  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      setswitchAccount(res ? true : false);
    });
  }, [route.params]);
  let [newsOrder, setNewOrder] = useState([]);
  const [dataDetil, setDataDetil] = useState(null);

  useEffect(() => {
    getdataHubCohub("", tabFlag);

  }, []);

  const selectedItem = (item) => {
    var params = {
      "no_dpp": item.idTransaksi
    }

    getDetilProductHubCoHub(params, token, "modal", item)
  }

  const onPresHDetil = (item) => {
    setItem(item)
    var params = {
      "idPencairan": item.idPencairan
    }

    getDetilProductHubCoHub(params, token, "page", item)
  }

  const goBack = (item) => {
    navigation.goBack()
  }

  const onPresHubSendConfirm = (value) => {
    setShowModalConfirm(!showModalConfirm)
    if (value) {
      navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Pengiriman Diproses', desc: 'Terimakasih , Pengiriman produk kamu telah berhasil dan sedang di proses , Klik tombol dibawah untuk cek status pengiriman kamu', titleButton: 'Kirim Pesanan Lainnya' })
    }
  }

  const selectSetTabFlag = async item => {
    setTabFlag(item.id);
    setTitle(item.name);
    setShowStatus(false);
    getdataHubCohub(search, item.id);
  }

  const getdataHubCohub = (search, status) => {

    getData(Constants.SESSION_USER_PROFILE).then(res => {

      if (res) {
        setToken(res.result.token);
      }

      var paramsListProduct = {
        search: search ? search : "",
        filter: status,
        pagination: 1,
        hubLocation: ''
      }

      getListProductHubCoHub(paramsListProduct, res.result.token);
    })
  }

  const getListProductHubCoHub = (params, token) => {
    setNewOrder([]);
    setLoading(true);
    JSONAxioGet(getURLHub('api_list_hub_setoran_cod', params), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        if (response.statusCode == 1) {
          setNewOrder(response.result);
        } else {

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack" }] });
        });
      });
    }

  }

  const onpressSelection = (item) => {
    var arraySelect = arraySelection;
    var result = arraySelect.filter(object => object?.no_dst === item?.no_dst);
    if(result.length == 0){
      
      setArraySelection([...arraySelection, item])
    } else {
      var result = arraySelect.filter(object => object?.no_dst !== item?.no_dst);
      setArraySelection(result)
    }
   
  }

  const checkSelection = (item) => {
    var result = arraySelection.filter(object => object?.no_dst == item?.no_dst); 
    return (result.length == 0 ? false : true)
  }


  const getDetilProductHubCoHub = (params, token, page, item) => {
    


    cekError(2, "Di Figma Belum Ada Nomor API nya ...");
    // setLoadingFull(true);
    // JSONAxioGet(getURLHub('api_status_cair_saldo', params), null, token)
    //   .then(respone => {
    //     setLoadingFull(false);
    //     const response = respone.data;

    //     if (response.statusCode == 1) {

    //       var isArray = Array.isArray(response.result);
    //       results = response.result;
    //       // setDataDetil(results)

    //       if (page === 'modal') {
    //         setShowModalConfirm(!showModalConfirm)
    //       } else {
    //         console.log(JSON.stringify(results))
    //         setDetil(results)
    //         // setShowModalStatus(true)
    //         // navigation.navigate(Routers.DETIL_COMITION_SCREEN, { data: results, item: item })
    //       }


    //     } else {

    //       cekError(response.statusCode, response.message);

    //     }
    //   })
    //   .catch(error => {
    //     setLoadingFull(false);
    //     console.log("error")
    //     cekError(4, null);
    //   });
  }

  const onpressOrder =() =>{
    setShowModalStatus(false)
    var parameter = arraySelection;
    parameter.map((item, i) => {
      delete item["nama_cohub"];
      delete item["total_dpp"];
      delete item["dpp_selesai"];
      delete item["nilaiCod"];
      delete item["sudah_disetor"];
      delete item["siap_disetor"];
    })

    var parameters = {
      "listDst": parameter
    }
    setLoadingFull(true)
    JSONAxioPost(postURL('api_prepare_setoran_cod', null), parameters,token)
        .then(respone => {
          const response = respone?.data;

          setLoadingFull(false);
          
          if (response?.statusCode == 1) {
              navigation.navigate(Routers.SUCCESS_SCREEN, {title: 'Setoran berhasil Diserahkan', desc:'Setoran anda sudah berhasil di serahkan', titleButton:'Kembali'})
          } else {
            setLoadingFull(false);
            cekError(response.statusCode, response.message);

          }
        })
        .catch(error => {
          setLoadingFull(false);
          cekError(2, null);

        });
  }

  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>


        {<View style={{ backgroundColor: Colors.white, flexDirection: 'row', paddingBottom: Scale(0), alignItems: 'center', justifyContent: 'center' }}>

          <View style={{ flex: 0.1, justifyContent: 'center', paddingLeft: Scale(8), marginTop: Scale(16) }}>
            <TouchableOpacity
              onPress={goBack}>
              <Image
                style={[{ height: Scale(30), width: Scale(30), tintColor: Colors.primaryColorHub }]}
                source={getIcon('ic_arrow_left_line')}
                resizeMode='contain' />
            </TouchableOpacity>

          </View>

          <View style={{ flex: 1 }}>
            <TextInput
              style={{ marginTop: Scale(20) }}
              onChange={value => setSearch(value)}
              icon={'ic_search'}
              value={search}
              placeholder={'Cari Trancaksi COD'}
              onPress={() => { getdataHubCohub(search, tabFlag) }}
              title={''}
              error={null}
            />
          </View>

        </View>}

        <TabLayout
          show={'readyToSend' != tabFlag ? true : false}
          title={title}
          titleType={titleType}
          openStatus={() => setShowStatus(true)}
          openType={() => setShowType(true)}
        />

        <View style={{ flex: 1 }}>

          <FlatList
            style={{ flex: 1, backgroundColor: Colors.greenWhite }}
            refreshing={loading}
            onRefresh={() => { getdataHubCohub(search, tabFlag) }}
            data={newsOrder.length == 0 ? [''] : newsOrder}
            renderItem={({ item, index }) =>
            (
              <View>
                {(newsOrder.length != 0) && 
                <ItemOrder
                checkBoxActive={checkSelection(item)}
                  onPressCheckBox = {(item) => onpressSelection(item)}
                  titleButtonDetil={'Ambil Pesanan'}
                  navigation={navigation}
                  key={index}
                  onPressSend={() => selectedItem(item)}
                  onPress={() => onPresHDetil(item)}
                  data={item} />}

                {(newsOrder.length == 0) && <View style={{ height: Metrics.screenHeight / 1.5, justifyContent: 'center', alignItems: 'center', paddingHorizontal: Scale(16) }}>

                  <Image
                    style={{ height: Scale(150), width: Scale(150) }}
                    source={getIcon('img_oops')}
                    resizeMode='contain' />

                  <Text style={{ fontSize: Scale(18), textAlign: 'center' }}>Maaf Anda belum ada transaksi apapun saat ini</Text>
                </View>}
              </View>
            )
            }
          />

          {arraySelection.length !== 0 && <View style={{ height: Scale(60), backgroundColor: Colors.gray, justifyContent:'center', }}>
            <View style={{ flexDirection: 'row', paddingHorizontal: Scale(8) }}>
              <View style={{ flex: 0.4, justifyContent:'center' }}>
                <Text style={[styles.text400, { color: Colors.black, fontSize: Scale(10) }]}>{'Total Nilai :'}</Text>
              </View>
              <View style={{ flex: 1, justifyContent:'center' }}>
                <Text style={[styles.text400, { color: Colors.red, fontSize: Scale(10) }]}>{'Dari API OBJECT-Nya STRING Tidak bisa di jumlahakan'}</Text>
              </View>

             <View style={{ flex: 1 }}>
                <Buttons
                  style={[{ backgroundColor: Colors.primaryColorHub, borderColor: Colors.primaryColorHub, borderWidth: Scale(1) }]}
                  styleTitle={{ color: Colors.white }}
                  onPress={() => setShowModalStatus(true)}
                  switchAccount={true}
                  title={("Serahkan (" +arraySelection.length+")")} />
              </View>
            </View>
          </View>}
        </View>

        <ModalStatusReadyToSend
          isHubSend={route.params?.isHubSend}
          isRiwayatCodHub={true}
          readySend={true}
          onPresStatus={(item) => selectSetTabFlag(item)}
          onClose={() => setShowStatus(false)}
          ShowStatus={showStatus} />

        <ModalConformationSendHub
          data={dataDetil}
          onPresButtonConfirm={(value) => onPresHubSendConfirm(value)}
          onCloses={() => setShowModalConfirm(false)}
          ShowComment={showModalConfirm}
          loading={(value) => setLoading(value)}
          cekError={(value1, value2) => cekError(value1, value2)}
        />

        <ModalSetoranCod
          hubPencairan ={true}
          statusPengiriman={arraySelection}
          // status={detilDataMyCard?.status_proses}
          onPresButtonOrder={() => onpressOrder()}
          onPresButton={() => console.log("")}
          onCloses={() => setShowModalStatus(false)}
          ShowComment={showModalStatus}
          // showKonfirmation={detilDataMyCard?.status_tombol_konfirmasi}
          // showImage={(value) => { openImage(value) }}
          title={false} />

        <Loading
          visible={loadingFull} />

        <PopUp
          visible={warning}
          onPressButton={() => { actionButton() }}
          title={contentWarning?.title}
          desc={contentWarning?.desc}
          titleButton={contentWarning?.titleButton} />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  imgRow: { height: Scale(90), width: Scale(90) },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
});
export default RiwayatCod;