// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  FlatList,
  PermissionsAndroid,
  Alert,
  Linking,
  Platform
} from 'react-native';
import { Colors } from '../../Assets/Colors';
import { getIcon } from '../../Assets/Icon';
import Toolbar from '../../Component/Toolbar';
import { Metrics, Scale } from '../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../Component/Button';
import { Routers } from '../../utils/Routers';
import { Constants } from '../../utils/Constans';
import { getData } from '../../utils/Storage';
import { currency } from '../../utils/General';
import RNFetchBlob from 'rn-fetch-blob';
import Clipboard from '@react-native-clipboard/clipboard';
import { ToastAndroid } from 'react-native';
import DeviceInfo, { getDeviceId, getSystemVersion, getBrand, getInstanceId } from 'react-native-device-info';

const PeymentGatewayScreen = ({ route, navigation }) => {

  var number = 0;
  let [switchAccount, setswitchAccount] = useState(false);
  // Time is in seconds
  const [time, setTime] = useState(route.params?.result?.timer);
  let [paymentMethode, setPaymentMethode] = useState(route.params?.paymentMethode)
  let [dataPayment, setDataPayment] = useState(route.params?.result);


  const goToMain = () => {
    navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
  }

  const goBack = (item) => {
    if (route.params?.transaction) {
      navigation.navigate(Routers.MAIN_PAGE, {
        screen: 'MyCartStack',
        params: { tab: 8 },
      })
    } else {
      navigation.goBack()
    }
  }

  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      setswitchAccount(res ? true : false);
      console.log("<<<< Data >>>> ");
    });

  }, []);

  const decrement = () =>
    setTime((prevTime) => {
      return prevTime === 0 ? 0 : prevTime - 1;
    });

  useEffect(() => {
    const id = setInterval(decrement, 1000);
    return () => clearInterval(id);
  }, []);


  const format = (num) => {
    return num < 10 ? '0' + num : num.toString();
  };

  const createdQrCode = () => {
    var url = null;

    if (dataPayment?.qris?.length > 0) {
      dataPayment.qris.map((item, i) => {
        if (item.name === "generate-qr-code") {
          url = item.url;
        }
      })
    }

    if (dataPayment?.gopay_actions.length > 0) {
      dataPayment?.gopay_actions.map((item, i) => {
        if (item.name === "generate-qr-code") {
          url = item.url;
        }
      })
    }

    if (dataPayment?.shopee_pay.length > 0) {
      dataPayment?.shopee_pay.map((item, i) => {
        if (item.name === "generate-qr-code") {
          url = item.url;
        }
      })

    }

    return url

  }

  const createdDeepLink = () => {
    var url = null;

    if (dataPayment?.qris?.length > 0) {
      dataPayment.qris.map((item, i) => {
        if (item.name === "deeplink-redirect") {
          url = item.url;
        }
      })
    }

    if (dataPayment?.gopay_actions.length > 0) {
      dataPayment?.gopay_actions.map((item, i) => {
        if (item.name === "deeplink-redirect") {
          url = item.url;
        }
      })
    }

    if (dataPayment?.shopee_pay.length > 0) {
      dataPayment?.shopee_pay.map((item, i) => {
        if (item.name === "deeplink-redirect") {
          url = item.url;
        }
      })

    }

    return url

  }

  const checkPermission = async (image) => {

    // Function to check the platform
    // If iOS then start downloading
    // If Android then ask for permission
    console.log("Platform.Version >> ", DeviceInfo.getSystemVersion());
    if (Platform.OS === 'ios') {
      downloadImage(image);
    } else {
      try {

        if (DeviceInfo.getSystemVersion() >= 13) {
          const granted = await PermissionsAndroid.request(
            PermissionsAndroid.PERMISSIONS.READ_MEDIA_IMAGES,
          );

          if (granted === PermissionsAndroid.RESULTS.GRANTED) {
            // Once user grant the permission start downloading
            console.log('Storage Permission Granted.');
            downloadImage(image);
          } else {
            // If permission denied then show alert
            console.log('Storage tidak Permission Granted.');
            const granted = await PermissionsAndroid.check(PermissionsAndroid.PERMISSIONS.READ_MEDIA_IMAGES);
          }

        } else {
          const granted = await PermissionsAndroid.request(
            PermissionsAndroid.PERMISSIONS.READ_EXTERNAL_STORAGE,
            PermissionsAndroid.PERMISSIONS.WRITE_EXTERNAL_STORAGE,
          );

          if (granted === PermissionsAndroid.RESULTS.GRANTED) {
            // Once user grant the permission start downloading
            console.log('Storage Permission Granted.');
            downloadImage(image);
          } else {
            // If permission denied then show alert
            console.log('Storage tidak Permission Granted.');
            const granted = await PermissionsAndroid.request(
              PermissionsAndroid.PERMISSIONS.READ_EXTERNAL_STORAGE,
              PermissionsAndroid.PERMISSIONS.WRITE_EXTERNAL_STORAGE,
            );
          }
        }


      } catch (err) {
        // To handle permission related exception
        console.warn(err);
      }
    }
  };

  const downloadImage = (url) => {
    // Main function to download the image

    // To add the time suffix in filename
    let date = new Date();
    // Image URL which we want to download
    let image_URL = url;
    // Getting the extention of the file
    let ext = getExtention(image_URL);
    ext = '.' + ext[0];
    // Get config and fs from RNFetchBlob
    // config: To pass the downloading related options
    // fs: Directory path where we want our image to download
    const { config, fs } = RNFetchBlob;
    let PictureDir = fs.dirs.DownloadDir;
    let options = {
      fileCache: true,
      addAndroidDownloads: {
        // Related to the Android only
        useDownloadManager: true,
        notification: true,
        path:
          PictureDir +
          '/QR_' +
          Math.floor(date.getTime() + date.getSeconds() / 2) +
          ".png",
        description: 'Image',
      },
    };
    config(options)
      .fetch('GET', image_URL)
      .then(res => {
        // Showing alert after successful downloading
        console.log('res -> ', JSON.stringify(res));
        Alert.alert('Yey !!!', ("Berhasil Download QR \nSilakan cek di folder download dengan nama " + 'QR_' +
          Math.floor(date.getTime() + date.getSeconds() / 2) +
          ".png"), [
          {
            text: '',
            // onPress: () => console.log('Cancel Pressed'),
            // style: 'cancel',
          },
          { text: 'OK', onPress: () => console.log("") },
        ]);
      });
  };

  const getExtention = filename => {
    // To get the file extension
    return /[.]/.exec(filename) ?
      /[^.]+$/.exec(filename) : undefined;
  };

  const createdNoRekOrVA = () => {
    var number = null;

    if (dataPayment?.va_pay.length > 0) {
      dataPayment.va_pay.map((item, i) => {
        number = item.va_number;
      })
    }

    if (dataPayment?.manual_pay.length > 0) {
      dataPayment.manual_pay.map((item, i) => {
        number = item.account_number;
      })
    }

    return number

  }

  const createdbankName = () => {
    var bank = null;

    if (dataPayment?.manual_pay.length > 0) {
      dataPayment.manual_pay.map((item, i) => {
        bank = item.bank;
      })
    }

    return bank

  }

  const createdUniqCode = () => {
    var number = null;

    if (dataPayment?.manual_pay.length > 0) {
      dataPayment.manual_pay.map((item, i) => {
        number = item.uniq_code;
      })
    }

    return number

  }

  const createdNumber = (index, item) => {
    var i_download = dataPayment?.desc_how_to?.findIndex(v => v.includes('Download Qr Code'));
    var i_scan = dataPayment?.desc_how_to?.findIndex(v => v.includes('Scan Qr Code'));


    if (index >= i_scan) {
      return (index - i_scan);
    } else if (index >= i_download) {
      return index.toString();
    }


  }


  const copied = (text) => {
    Clipboard.setString(createdNoRekOrVA().toString())
    ToastAndroid.show('Salin', ToastAndroid.CENTER);
  }

  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>
        <Toolbar
          onPress={goBack}
          title={'Pembayaran'} />

        <ScrollView>
          <View style={{ flex: 1, marginTop: Scale(10) }}>



            {createdQrCode() && <View style={{ flexDirection: 'row', marginHorizontal: Scale(paymentMethode?.icon ? 16 : 0) }}>
              {paymentMethode.icon && <View style={{ flex: (paymentMethode?.icon === "ic_qris" ? 0.3 : 1), justifyContent: 'center', marginRight: Scale(8) }}>
                <Image
                  style={{ height: paymentMethode.height, width: paymentMethode.width }}
                  source={getIcon(paymentMethode.icon)}
                  resizeMode='stretch' />
              </View>}

              {paymentMethode?.icon === "ic_qris" && <View style={{ flex: 1, justifyContent: 'center' }}>
                {<Text style={{ color: Colors.black, fontWeight: 'bold', fontSize: Scale(8) }}>{"QR Code Standar \n Pembayaran Nasional"}</Text>}
              </View>}
            </View>}

            <View style={{ paddingHorizontal: Scale(16), justifyContent: 'center', alignItems: 'center' }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', marginHorizontal: Scale(paymentMethode?.icon ? 8 : 0), marginVertical: Scale(16) }}>

                <Text style={{ color: Colors.black, fontWeight: 'bold', fontSize: Scale(14) }}>{"Batas Waktu Pembayaran"}</Text>

                <View style={{ flex: 1, justifyContent: 'center', alignItems: 'flex-end' }}>
                  {<Text style={{ color: Colors.red, fontWeight: 'bold', fontSize: Scale(14) }}>{format(Math.floor(time / (3600 * 24))) + " : " + format(Math.floor((time / 3600) % 24)) + " : " + format(Math.floor((time / 60) % 60)) + " : " + format(time % 60)}</Text>}
                </View>
              </View>

              {createdQrCode() && <View>
                {<Text style={{ color: Colors.black, fontWeight: 'bold', fontSize: Scale(14), textAlign: 'center' }}>{paymentMethode?.name}</Text>}
                {<Text style={{ color: Colors.black, fontWeight: '300', fontSize: Scale(14), marginVertical: Scale(12), textAlign: 'center' }}>{"NMID : " + dataPayment?.order_id}</Text>}
              </View>}



              {createdQrCode() && <Image
                style={{ height: Scale(200), width: Scale(200), marginHorizontal: Scale(8) }}
                source={{ uri: createdQrCode() }}
                resizeMode='contain' />}

              {createdQrCode() && <View>
                <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14), marginTop: Scale(18), textAlign: 'center' }}>{"Total Pembayaran"}</Text>
                <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14), marginTop: Scale(18), textAlign: 'center' }}>{"Rp. " + currency(dataPayment?.gross_amount)}</Text>
              </View>}

              {createdQrCode() && <Buttons
                style={{ marginTop: Scale(40), width: Metrics.screenWidth / 1.2, backgroundColor: "#6495ED" }}
                onPress={() => checkPermission(createdQrCode())}
                title={"Unduh QR"} />}




              {(createdNoRekOrVA() || createdbankName()) && <View style={{ flexDirection: 'row', borderBottomColor: Colors.gray, borderBottomWidth: Scale(1), borderTopColor: Colors.gray, borderTopWidth: Scale(1), paddingVertical: Scale(16), marginHorizontal: Scale(paymentMethode?.icon ? 8 : 0) }}>

                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14) }}>{"Total Pembayaran"}</Text>
                </View>

                <View style={{ flex: 1, alignItems: 'flex-end', justifyContent: 'center' }}>
                  <Text style={{ color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor, fontWeight: '600', fontSize: Scale(14) }}>{"Rp. " + currency(dataPayment?.gross_amount)}</Text>
                </View>



              </View>}

              {(createdUniqCode() && dataPayment?.manual_pay[0].uniq_code) && <View style={{ flexDirection: 'row', borderBottomColor: Colors.gray, borderBottomWidth: Scale(1), borderTopColor: Colors.gray, borderTopWidth: Scale(1), paddingVertical: Scale(16), marginHorizontal: Scale(paymentMethode?.icon ? 8 : 0) }}>

                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14) }}>{"Kode Unik"}</Text>
                </View>

                <View style={{ flex: 1, alignItems: 'flex-end', justifyContent: 'center' }}>
                  <Text style={{ color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor, fontWeight: '600', fontSize: Scale(14) }}>{createdUniqCode()}</Text>
                </View>



              </View>}




            </View>

            {(createdNoRekOrVA() || createdbankName()) && <View style={{ flexDirection: 'row', borderBottomColor: Colors.gray, borderTopColor: Colors.gray, borderTopWidth: Scale(10), paddingVertical: Scale(16), paddingHorizontal: Scale(paymentMethode?.icon ? 24 : 0) }}>

              <View style={{ flex: 0.2, alignItems: 'center', marginRight: Scale(8) }}>
                <Image
                  style={{ height: paymentMethode.height, width: paymentMethode.width }}
                  source={getIcon(paymentMethode.icon)}
                  resizeMode='contain' />
              </View>
              <View style={{ flex: 1, justifyContent: 'center' }}>
                {<Text style={{ color: Colors.black, fontWeight: '200' }}>{" " + paymentMethode?.category ? (paymentMethode.category + ' ' + paymentMethode?.name) : paymentMethode?.name}</Text>}
              </View>
            </View>}

            {createdNoRekOrVA() && <View style={{ borderBottomColor: Colors.gray, borderBottomWidth: Scale(1), borderTopColor: Colors.gray, borderTopWidth: Scale(1), paddingVertical: Scale(16), marginHorizontal: Scale(22) }}>

              <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(12), marginBottom: Scale(8) }}>{dataPayment?.va_pay.length > 0 ? "Virtual Account" : "No. Rekening"}</Text>

              <View style={{ flexDirection: 'row' }}>

                <View style={{ flex: 1, justifyContent: 'center' }}>
                  <Text style={{ color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor, fontWeight: '600', fontSize: Scale(14) }}>{createdNoRekOrVA()}</Text>
                </View>

                <TouchableOpacity
                  style={{ flex: 1 }}
                  onPress={() => copied()}>
                  <View style={{ alignItems: 'flex-end', justifyContent: 'center' }}>
                    <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(12) }}>{"Salin"}</Text>
                  </View>
                </TouchableOpacity>

              </View>
            </View>}

            {createdNoRekOrVA() && dataPayment?.manual_pay.length > 0 && <View style={{ borderBottomColor: Colors.gray, borderBottomWidth: Scale(1), borderTopColor: Colors.gray, borderTopWidth: Scale(1), paddingVertical: Scale(16), marginHorizontal: Scale(22) }}>

              {createdNoRekOrVA() && <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(12), marginBottom: Scale(8) }}>{"Nama Rekening"}</Text>}

              <View style={{ flexDirection: 'row' }}>

                <View style={{ flex: 1, justifyContent: 'center' }}>
                  <Text style={{ color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor, fontWeight: '600', fontSize: Scale(14) }}>{dataPayment?.manual_pay[0].account_name}</Text>
                </View>

              </View>
            </View>}

            {dataPayment?.process_note && <Text style={[styles.text40012, { fontSize: Scale(14), color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor, marginVertical: Scale(16), marginHorizontal: Scale(22) }]}>{dataPayment?.process_note}</Text>}

            <View style={{ paddingHorizontal: Scale(16) }}>
              <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14), marginTop: Scale(18) }}>{"Tata Cara Pembayaran"}</Text>

              {

                dataPayment?.desc_how_to != null && dataPayment?.desc_how_to?.includes('Download Qr Code') && dataPayment?.desc_how_to.map((item, i) => {

                  return (<View style={{ marginVertical: Scale(8), paddingHorizontal: Scale((item?.includes('Download Qr Code') || item?.includes('Scan Qr Code')) ? 0 : 16) }}>

                    <View style={{ flexDirection: 'row', marginTop: Scale(10) }}>
                      {(!item?.includes('Download Qr Code') && !item?.includes('Scan Qr Code')) && <View style={{ flex: 0.1, justifyContent: 'center' }}>
                        <View style={{
                          width: (item?.includes('Download Qr Code') || item?.includes('Scan Qr Code')) ? 0 : 18,
                          height: (item?.includes('Download Qr Code') || item?.includes('Scan Qr Code')) ? 0 : 18,
                          borderRadius: (item?.includes('Download Qr Code') || item?.includes('Scan Qr Code')) ? 0 : 18 / 2,
                          backgroundColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor,
                          justifyContent: 'center',
                          alignItems: 'center'
                        }}>
                          <Text style={[styles.text40012, { fontSize: Scale(12), color: Colors.white }]}>{createdNumber(i, item)}</Text>
                        </View>

                      </View>}
                      <View style={{ flex: 1 }}>
                        <Text style={[styles.text40012, { fontSize: Scale(14), color: (item?.includes('Download Qr Code') || item?.includes('Scan Qr Code')) ? Colors.black : (switchAccount ? Colors.primaryColorHub : Colors.primaryColor) }]}>{item}</Text>
                      </View>
                    </View>
                  </View>)
                })}

              {dataPayment?.desc_how_to != null && !dataPayment?.desc_how_to?.includes('Download Qr Code') && dataPayment?.desc_how_to.map((item, i) => (
                <View style={{ marginVertical: Scale(8) }}>

                  <View style={{ flexDirection: 'row', marginTop: Scale(10) }}>
                    <View style={{ flex: 0.1, justifyContent: 'center' }}>
                      <View style={{
                        width: 24,
                        height: 24,
                        borderRadius: 24 / 2,
                        backgroundColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor,
                        justifyContent: 'center',
                        alignItems: 'center'
                      }}>
                        <Text style={[styles.text40012, { fontSize: Scale(12), color: Colors.white }]}>{(i + 1)}</Text>
                      </View>

                    </View>
                    <View style={{ flex: 1 }}>
                      <Text style={[styles.text40012, { fontSize: Scale(14), color: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }]}>{item}</Text>
                    </View>
                  </View>
                </View>
              ))}

              <View style={{ justifyContent: 'center', alignItems: 'center' }}>

                {createdDeepLink() && <Buttons
                  switchAccount={switchAccount}
                  style={{ marginTop: Scale(40), width: Metrics.screenWidth / 1.2, }}
                  onPress={() => { Linking.openURL(createdDeepLink()); }}
                  title={"Buka Aplikasi " + paymentMethode?.name} />}

                <Buttons
                  switchAccount={switchAccount}
                  style={{ marginTop: Scale(createdDeepLink() ? 8 : 40), width: Metrics.screenWidth / 1.2, }}
                  onPress={goToMain}
                  title={route.params?.titleButton ? route.params?.titleButton : 'Belanja Lagi'} />

              </View>

            </View>


          </View>
        </ScrollView>





      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default PeymentGatewayScreen;