import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  FlatList
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Toolbar from '../../../Component/Toolbar';
import { Metrics, Scale } from '../../../utils/size';
import TextInput from '../../../Component/TextInput';
import Buttons from '../../../Component/Button';
import { getData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';

const EditProfile = ({route, navigation }) => {

  let [profesi, setProfesi] = useState([
    { name: "Personal", status: true },
    { name: "Hub", status: false }]
    );
    let [switchAccount, setswitchAccount] = useState(false);
    useEffect(() => {

      getData(Constants.SESSION_HUB).then(res => {
        setswitchAccount(res ? true :  false);
      });
      
    }, [route.params]);

  const onPressProfesi =(index)=>{

    profesi.map((item, i) => {
      item.status = false;

      if (i == index){
        item.status = true;
      }
    })
    setProfesi([...profesi])
  }

  

  const goBack =(item)=>{
    navigation.goBack()
  }
  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
        switchAccount={switchAccount}
        styleIcon = {{tintColor : Colors.white}}
        styleTitle ={{color : Colors.white}}
        styleContainer={{backgroundColor: switchAccount ? Colors.primaryColorHub :Colors.primaryColor, borderBottomColor: switchAccount ? Colors.primaryColorHub :Colors.primaryColor}}
        onPress={goBack}
        title={'Ubah Profile'} />

        <View style={{ height: Scale(175)}}>

          <View style={{ position: 'absolute', top: Scale(0), backgroundColor: switchAccount ? Colors.primaryColorHub :Colors.primaryColor, width: Metrics.screenWidth, height: Scale(60) }} />

          <View style={{ alignSelf: 'center', marginTop: Scale(10) }}>
            <Image
              style={styles.imgRow}
              source={getIcon('ic_user')}
              resizeMode='contain' />

            <Text style={{ padding: Scale(8), backgroundColor: switchAccount ? Colors.primaryColorHub :Colors.primaryColor, color: Colors.white, marginVertical: Scale(8), borderRadius: Scale(8), textAlign: 'center' }}>{"Ganti Photo"}</Text>
          
          </View>

          <View style={{backgroundColor : switchAccount ? Colors.primaryColorHub :Colors.primaryColor, height: Scale(1), marginHorizontal: Scale(16), marginVertical: Scale(16)}}/>
        </View>

        <ScrollView>
          <View style={{ flex: 1 }}>


           
            
            <TextInput
              // onChange={}
              // icon={} 
              // value={} 
              placeholder={'Nama'}
              //  onPress
              title={'Nama'}
              error={null}
            />

            <TextInput
              // onChange={}
              // icon={} 
              // value={} 
              placeholder={'Email'}
              //  onPress
              title={'Email'}
              error={null}
            />

            <TextInput
              // onChange={}
              // icon={} 
              // value={} 
              placeholder={'No Ktp'}
              //  onPress
              title={'No Ktp'}
              error={null}
            />

            <TextInput
              // onChange={}
              // icon={} 
              // value={} 
              placeholder={'Alamat'}
              //  onPress
              title={'Alamat'}
              error={null}
            />

            <TextInput
              // onChange={}
              // icon={} 
              // value={} 
              placeholder={'Profesi'}
              //  onPress
              title={'Profesi'}
              error={null}
            />



            <View style={{ flexDirection: 'row', paddingHorizontal: Scale(20), paddingVertical: Scale(16) }}>
              
              {profesi && profesi.map((item, i) => ( 
              
              <View style={{flex:1, flexDirection: 'row' }}>
                <View style={{ flex: 0.2 }}>
                    <TouchableOpacity
                      onPress={() => onPressProfesi(i)}>
                      <Image
                        style={{ height: Scale(20), width: Scale(20) }}
                        source={getIcon(item.status ? 'radio_button_on' : 'radio_button_off')}
                        resizeMode='contain' />
                    </TouchableOpacity>
                  </View>
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.text400]}>{item.name}</Text>
                  </View>
                </View>
            
              ))}

            </View>



            <Buttons
              switchAccount ={switchAccount}
              style={{ marginTop: Scale(40), marginHorizontal: Scale(16), }}
              onPress={() => console.log("safasdas")}
              title={'Ubah'} />


          </View>
        </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  imgRow: { height: Scale(90), width: Scale(90) },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
});
export default EditProfile;