// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  ScrollView,
  SafeAreaView,
  Alert
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Toolbar from '../../../Component/Toolbar';
import { Metrics, Scale } from '../../../utils/size';
import TextInput from '../../../Component/TextInput';
import Buttons from '../../../Component/Button';
import { Constants } from '../../../utils/Constans';
import { getData, removeData } from '../../../utils/Storage';
import { JSONAxioPostFile } from '../../../utils/services/JsonService';
import { postURL } from '../../../utils/services/API';
import { Routers } from '../../../utils/Routers';

const EditPassword = ({route, navigation }) => {
  const {forgote} = route.params;
  let [switchAccount, setswitchAccount] = useState(false);
  let [profesi, setProfesi] = useState([
    { name: "Personal", status: true },
    { name: "Hub", status: false }]
    );

    let [eyeBeforePass, setEyeBeforePass] = useState(false);
    let [eyePass, setEyePass] = useState(false);
    let [eyeConfirmPass, setEyeConfirmPass] = useState(false);

    let [loading, setLoading] = useState(false);
    let [email, setEmail] = useState(null);
    let [oldPassword, setOldPassword] = useState(null);
    let [password, setPassword] = useState(null);
    let [confirmationPassword, setConfirmationPassword] = useState(null);

    let [oldPasswordError, setOldPasswordError] = useState(null);
    let [emailError, setEmailError] = useState(null);
    let [passwordError, setPasswordError] = useState(null);
    let [confirmationPasswordError, setConfirmationPasswordError] = useState(null);
    let [errorMessage, setErrorMessage] = useState(null);
    let [login, setLogin] = useState(null);

    useEffect(() => {
      getData(Constants.SESSION_HUB).then(res => {
        setswitchAccount(res ? true :  false);
      });

      getData(Constants.SESSION_USER_PROFILE).then(res => {
        console.log(res);
        setLogin(res);
      })
    }, [route.params]);


  const createTwoButtonAlert = (desc) =>
    Alert.alert('Yey !!!', desc, [
      {
        text: '',
        onPress: () => console.log('Cancel Pressed'),
        style: 'cancel',
      },
      { text: 'OK', onPress: () => goBack() },
    ]);

    const clickButton =()=>{
      setEmailError(null);
      setOldPasswordError(null);
      setPasswordError(null);
      setConfirmationPasswordError(null);
      setErrorMessage(null);

      if (forgote){
        if (!validationForgotePassword()){
          postForgotePassword()
        }
      } else {
        if (!validationChangedPassword()){
          postChangedPassword()
        }
      }
      
    }

  const validationChangedPassword = () => {
    var isError = false;
    if (oldPassword == '' || null == oldPassword) {
      setOldPasswordError("Harap masukan password lama Anda");
      isError = true;
    }

    if (password == '' || null == password) {
      setPasswordError("Harap masukan password");
      isError = true;
    }

    if (confirmationPassword == '' || null == confirmationPassword) {
      setConfirmationPasswordError("Harap masukan konfirmasi password");
      isError = true;
    }

    if (password != '' || null != password || confirmationPassword != '' || null != confirmationPassword) {

      if (password != confirmationPassword) {
        setConfirmationPasswordError("Konfirmasi password tidak sama");
        setPasswordError("Konfirmasi password tidak sama");
        isError = true;
      }
    }

    return isError;

  }

  const validationForgotePassword = () => {
    var isError = false;

    // if (email == '' || null == email) {
    //   setEmailError("Harap masukan Email Anda");
    //   isError = true;
    // }

    if (password == '' || null == password) {
      setPasswordError("Harap masukan password");
      isError = true;
    }

    if (confirmationPassword == '' || null == confirmationPassword) {
      setConfirmationPasswordError("Harap masukan konfirmasi password");
      isError = true;
    }

    if (password != '' || null != password || confirmationPassword != '' || null != confirmationPassword) {

      if (password != confirmationPassword) {
        setConfirmationPasswordError("Konfirmasi password tidak sama");
        setPasswordError("Konfirmasi password tidak sama");
        isError = true;
      }
    }

    return isError;

  }

  const postChangedPassword =()=>{

    var param = {
      userid:login.result.hp,
      passOld:oldPassword,
      passNew :password,
      repassNew: confirmationPassword,
      typeRequest:'rubah'
    }

    console.log(param);
    setLoading(true);

    JSONAxioPostFile(postURL('changed'), param, null)
    .then(respone => {
      const response = respone.data;
      console.log(response);
      setLoading(false);
      if (response.statusCode > 1) {
        setOldPasswordError(response.message);
        setPasswordError(response.message);
        setConfirmationPasswordError(response.message);
      } else {
        createTwoButtonAlert(response.message);
      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
      const message = error.toJSON().message;
      setOldPasswordError(message);
      setPasswordError(message);
      setConfirmationPasswordError(message);
    });
  }

  const postForgotePassword =()=>{

    var param = {
      userid:email,
      email:email,
      passNew :password,
      repassNew: confirmationPassword,
      typeRequest:'lupa'
    }

    setLoading(true);

    JSONAxioPostFile(postURL('api_reset_lupas'), param, route.params?.tokenOtp)
    .then(respone => {
      const response = respone.data;
      console.log(response);
      setLoading(false);
      if (response.statusCode > 1) {
        setOldPasswordError(response.message);
        setPasswordError(response.message);
        setConfirmationPasswordError(response.message);
      } else {
        createTwoButtonAlert(response.message);
      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
      const message = error.toJSON().message;
      setOldPasswordError(message);
      setPasswordError(message);
      setConfirmationPasswordError(message);
    });
  }
  

  const goBack =(item)=>{
    if (forgote) {
      navigation.navigate(Routers.FORGOTE_PASSWORD_SCREEN, {forgote: true});
    } else {
      navigation.goBack()

    }
  }
  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
        switchAccount ={switchAccount}
        onPress={goBack}
        title={forgote ? 'Lupa Kata Sandi' :'Ubah Kata Sandi'} />


        <Text style={[styles.text400,{marginVertical: Scale(16), marginHorizontal: Scale(16)}]}>{'Kami Akan Mengirimi Kode \nVerifikasi Ke Email Anda'}</Text>

        <View style={{height: Scale(1), backgroundColor: Colors.gray, marginVertical: Scale(16), marginHorizontal: Scale(16)}}/>
        <ScrollView>
          <View style={{ flex: 1 }}>

            {/* {forgote && <TextInput
              onChange={value => {
                setEmail(value);
              }}
              // icon={} 
              // value={} 
              placeholder={'Email'}
              //  onPress
              title={'Email'}
              error={emailError}
              editable={!loading}
            />} */}

            {!forgote && <TextInput
               onChange={value => {
                setOldPassword(value);
              }}
              icon={eyeBeforePass ? 'ic_eye_open' : 'ic_eye_close'}
              // value={} 
              placeholder={'Masukan Kata Sandi Sebelumnya'}
              onPress={() => setEyeBeforePass(!eyeBeforePass)}
              title={'Kata Sandi Sebelumnya'}
              secureTextEntry={!eyeBeforePass}
              error={oldPasswordError}
              editable={!loading}
            />}

            <TextInput
              onChange={value => {
                setPassword(value);
              }}
              icon={eyePass ? 'ic_eye_open' : 'ic_eye_close'}
              // value={} 
              placeholder={'Masukan Kata Sandi Baru'}
              onPress={() => setEyePass(!eyePass)}
              title={'Kata Sandi Baru'}
              secureTextEntry={!eyePass}
              editable={!loading}
              error={passwordError}
            />

            <TextInput
               onChange={value => {
                setConfirmationPassword(value);
              }}
              icon={eyeConfirmPass ? 'ic_eye_open': 'ic_eye_close'}
              // value={} 
              placeholder={'Masukan Konfirmasi Kata Sandi Baru'}
              onPress={() => setEyeConfirmPass(!eyeConfirmPass)}
              title={'Konfirmasi Kata Sandi Baru'}
              secureTextEntry={!eyeConfirmPass}
              editable={!loading}
              error={confirmationPasswordError}
            />
            <Buttons
              switchAccount ={switchAccount}
              loading={loading}
              disabled={loading}
              style={{ marginTop: Scale(40), marginHorizontal: Scale(16), backgroundColor: loading ? Colors.greenWhite : (switchAccount ? Colors.primaryColorHub: Colors.primaryColor) }}
              onPress={() => clickButton()}
              title={'Ubah'} />


          </View>
        </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  imgRow: { height: Scale(90), width: Scale(90) },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
});
export default EditPassword;