// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useState }  from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  SafeAreaView,
  TextInput as TextInputs
} from 'react-native';
import { Colors } from '../../Assets/Colors';
import { getIcon } from '../../Assets/Icon';
import { Scale } from '../../utils/size';

const TextInput = ({onChange, onPress, icon, value, placeholder,title, error, style, secureTextEntry, editable, keyboardType}) => {
  let [activeLogin, setActiveLogin] = useState(true);
  let [activeRegister, setActiveRegister] = useState(false);

  return (
      <View style ={[{ marginHorizontal: Scale(16), marginVertical: Scale(4) }, style]}>
          {title && <Text
              style={{
                  fontSize: Scale(12),
                  color: (Colors.black),
                  fontWeight: '600',
                  marginHorizontal: Scale(18),
                  marginVertical: Scale(8)
              }}>
              {title}
          </Text>}

          <View style={{ backgroundColor: Colors.gray, height: Scale(50),borderRadius: Scale(20), justifyContent: 'center' }}>
             
              <View style={{ flexDirection: 'row' }}>
                  <View style={[{ flex: 1, height: Scale(35), borderRadius: Scale(20) }]} >
                      <TextInputs
                        style = {[{paddingHorizontal: Scale(16), fontSize: Scale(12)}]}
                          onChangeText={onChange}
                          value={value}
                          editable={editable}
                          placeholder={placeholder}
                          secureTextEntry={secureTextEntry}
                          keyboardType= {keyboardType ? keyboardType :"default"}
                      />
                  </View>

                 {icon && <TouchableOpacity
                      style={{ flex: 0.2, height: Scale(35), backgroundColor: (activeRegister ? Colors.primaryColor : Colors.gray), borderRadius: Scale(20), marginRight: Scale(6), justifyContent: 'center', alignItems: 'center' }}
                      onPress={onPress}>
                      <View >
                          <Image
                              style={{ height: Scale(20), width: Scale(20), marginHorizontal: Scale(8) }}
                              source={getIcon(icon)} 
                              resizeMode='contain'/>
                      </View>
                  </TouchableOpacity>}

              </View>

          </View>
          {error && <Text
              style={{
                  fontSize: Scale(12),
                  color: (Colors.red),
                  marginHorizontal: Scale(14),
                  marginVertical: Scale(4),
                  fontStyle: 'italic'
              }}
              >
              {error}
          </Text>}
      </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default TextInput;