import React, { useEffect, useState } from 'react';
import {
  StyleSheet,
  View,
  Text,
  Image,
  FlatList,
  TouchableOpacity
} from 'react-native';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import { Metrics, Scale } from '../../../../utils/size';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import { Routers } from '../../../../Constansutils/Routers';
import { getData } from '../../../../utils/Storage';
import { Constants } from '../../../../utils/Constans';
import Buttons from '../../../../Component/Button';

const ItemOrder = ({ navigation, data, onPress, titleButton, titleButtonDetil, onPressSend  }) => {
  let [menu, setMenu] = useState([
    {name : 'Pesanan Baru', icon: 'ic_new_order'}, 
    {name : 'Ambil Pesanan', icon: 'ic_new_send'},
    {name : 'Order Retur', icon: 'ic_retur_order'},
    {name : 'Finance', icon: 'ic_finance'},
    {name : 'Inventory', icon: 'ic_inventory'},
    {name : 'Logistik', icon: 'ic_logistic'}, 
  ]);

  let [hub, setHub] = useState(true)

  useEffect(() => {

    getData(Constants.SESSION_HUB).then(res => {
     if (res){

       if (JSON.parse(res).userRole === "HUB"){
        setHub(true)

       } else if (JSON.parse(res).userRole === "COHUB") {
        setHub(false)
       }

     } else {
      
     }
    })
 }, []);

  return (
      <View style={{flex :1, backgroundColor: Colors.white, padding: Scale(8), marginHorizontal: Scale(16), marginVertical: Scale(8),  }}>
        <View style={{ flexDirection: 'row'}}>
          {/* <View style={{ flex: 0.4 }}>
            <TouchableOpacity
            onPress={() => onPress()}>
            <Image
              style={{ height: Scale(77), width: Scale(80) }}
              source={{
                uri: data.img_url
              }}
              resizeMode="contain"
            />
            </TouchableOpacity>
          </View> */}
          <View style={{ flex: 1 }}>

            <View style={{ flexDirection: 'row', marginVertical: Scale(4) }}>

              <View style={{ flex: 1 }}>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10) }]}>{'Nomor Pencairan'}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{"Tanggal"}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8) }]}>{"Pencairan"}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10), marginVertical: Scale(8)  }]}>{"Jumlah Withdraw"}</Text>
                <Text style={[styles.text40012, { color: Colors.black, fontSize: Scale(10) }]}>{"Status"}</Text>
              </View>

              <View style={{ flex: 1, alignItems:'flex-end' }}>
              <Text style={[styles.text40012, { color: Colors.primaryColorHub }]}>{data?.idPencairan}</Text>
              <Text style={[styles.text40012, { color: Colors.primaryColorHub, marginVertical: Scale(8) }]}>{data?.tanggalPencairan}</Text>
              <Text style={[styles.text40012, { color: Colors.primaryColorHub }]}>{data?.tipe_wallet}</Text>
              <Text style={[styles.text40012, { color: Colors.primaryColorHub, marginVertical: Scale(8) }]}>{data?.jumlah}</Text>
              <Text style={[styles.text40012, { color: Colors.primaryColorHub }]}>{data?.status}</Text>
              </View>
            </View>

          </View>


        </View>
        
      <Buttons
        style={[{ backgroundColor: Colors.white, borderColor: Colors.primaryColorHub, borderWidth: Scale(1) }]}
        styleTitle={{ color: Colors.primaryColorHub }}
        onPress={() => onPress()}
        switchAccount={true}
        title={("Lihat Detail")} />

      </View>
  );
}

const styles = StyleSheet.create({
  container: {flex:1},
  containerRow: { flexDirection: 'row' },
  imgRow: { height: Scale(40), width: Scale(40) },
  viewCenter: { flex: 1, justifyContent: 'center' },
  viewCenterPadding: { paddingLeft: Scale(16), paddingRight: Scale(16) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text60012: { color: Colors.black, fontWeight: '600', fontSize: Scale(12) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
  text40014: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  viewRowSaldo: { flexDirection: 'row', height: Scale(60), backgroundColor: Colors.gray, marginVertical: Scale(8), borderRadius: Scale(10), padding: Scale(10) }

});
export default ItemOrder;