// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  RefreshControl,
  FlatList,
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Toolbar from '../../../Component/Toolbar';
import { Scale } from '../../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../../Component/Button';
import { Routers } from '../../../utils/Routers';
import { JSONAxioGet,JSONAxioDelete } from '../../../utils/services/JsonService';
import { getURL,postURL, deleteURL } from '../../../utils/services/API';
import { Constants } from '../../../utils/Constans';
import { getData } from '../../../utils/Storage';

const ProvinceScreen = ({ route, navigation }) => {

  let [dataProv, setDataProv] = useState([]);
  let [token, setToken] = useState(0)
  let [loading, setLoading] = useState(false)
  let [flag, setFlag] = useState(route.params?.flag)
  let [province, setProvince] = useState(route.params?.data?.propinsi);
  let [city, setCity] = useState(route.params?.data?.kota);
  let [kecamatan, setKecamatan] = useState(route.params?.data?.kecamatan);

    useEffect(() => {
      getdata()
      const unsubscribe = navigation.addListener('focus', () => {
        getdata();
        //Put your Data loading function here instead of my loadData()
      });
  
      return unsubscribe;

    }, [token, navigation, province, city, kecamatan]);

  const selectAddres =(item)=>{

    if (flag =='province'){
      setFlag('city');
      setProvince(item)  
      getdata()
    } else if (flag =='city'){
      setFlag('kecamatan');
      setCity(item)
      getdata() 
    } else if (flag =='kecamatan'){
      setKecamatan(item)
      var data = {
        idalamat: route.params?.data?.idalamat,
        propinsi: province,
        kota: city,
        kecamatan: item,
        kodepos: route.params?.data?.kodepos,
        as_lokasi: route.params?.data?.as_lokasi,
        atur_utama: route.params?.data?.atur_utama,
        nama_penerima: route.params?.data?.nama_penerima,
        catatan_tambahan: route.params?.data?.catatan_tambahan,
        address: route.params?.data?.address,
        handphone:route.params?.data?.handphone,
        title:route.params?.data?.title,
        utama:route.params?.data?.utama,
       

      }

      navigation.navigate(Routers.ADDRESS_SCREEN, {data : data,  title: route.params?.data.title})
    }

    // navigation.navigate(Routers.PROVINCE_SCREEN, {address : item})


  }

  const goBack =(item)=>{
    navigation.goBack()
  }


  const getdata = () => {
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      
      setToken(res.result.token)
      if (flag == 'province') {
        getListProvince();
      } else if (flag == 'city') {
        getListCity();
      } else if (flag == 'kecamatan') {
        getListKecamatan();
      }
     })
  }

  

  const getListKecamatan = (params) => {
    setLoading(true)
    setDataProv([])
    JSONAxioGet(getURL('api-get-kecamatan', {id_kota: city.id_kota}), null, token)
    .then(respone => {
      setLoading(false);
      
      const response = respone.data;
      if (response.statusCode == 1) {
        setDataProv(response.result)
      } else {
       
      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
    });
  }

  const getListCity = (params) => {
    setLoading(true)
    setDataProv([])
    JSONAxioGet(getURL('api-get-kota', {id_propinsi : province.id_propinsi}), null, token)
    .then(respone => {
      setLoading(false);
      
      const response = respone.data;
      if (response.statusCode == 1) {
        setDataProv(response.result)
      } else {
       
      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
    });
  }

  const getListProvince = (params) => {
    setLoading(true)
    setDataProv([])
    JSONAxioGet(getURL('api-get-propinsi', null), null, token)
    .then(respone => {
      setLoading(false);
      
      const response = respone.data;
      if (response.statusCode == 1) {
        setDataProv(response.result)
      } else {
       
      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
    });
  }


  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.greenWhite }}>

        <Toolbar
          style = {{marginVertical : Scale(-30), marginBottom : Scale(8), marginLeft : Scale(0), backgroundColor: Colors.greenWhite}}
          styleContainer ={{backgroundColor: Colors.greenWhite}}
          onPress={goBack}
          placeholder={"Cari "+ (flag == "province" ? 'Provinsi' : flag == "city" ? 'Kota' : "Kecamatan")}
          searchMap />

          <ScrollView
          refreshControl={
            <RefreshControl refreshing={loading} onRefresh={getdata} />
          }>

            <View style={{flex:1}}>

              {
                dataProv.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2), }}>
                    <TouchableOpacity
                      onPress={() => selectAddres(item)}>
                      <View style={{}}>
                        <View style={{ flexDirection: 'row' }}>
                        

                          <View style={{ flex: 1 }}>
                            <View style ={{flexDirection : 'row'}}>
                                <View style={{flex:1}}>
                                <Text style={{ color: Colors.primaryColor, fontWeight: '600' }}>{flag =='province' ? item.nama_propinsi : flag =='city' ? item.nama_kota :item.nama_kecamatan }</Text>
                                </View>
                            </View>
                            

                           

                          </View>
                         
                        </View>
                      </View>
                    </TouchableOpacity>
                  </View>
                ))
            }
             



            </View>
          </ScrollView>
          

        </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default ProvinceScreen;