import AsyncStorage from '@react-native-async-storage/async-storage';
// import {showMessage} from '../showMessage';
// import {Strings} from '../../assets';

export const storeData = async (storageKey, value) => {
  try {
    const jsonValue = JSON.stringify(value);
    await AsyncStorage.setItem(storageKey, jsonValue);
  } catch (e) {
    // showMessage(Strings.txt_failed_save_localstorage);
  }
};

export const getData = async storageKey => {
  try {
    const jsonValue = await AsyncStorage.getItem(storageKey);
    return jsonValue != null ? JSON.parse(jsonValue) : null;
  } catch (e) {
    // showMessage(Strings.txt_failed_get_localstorage);
  }
};

export const removeData = async removeKey => {
  try {
    await AsyncStorage.removeItem(removeKey);
  } catch (e) {
    // showMessage(String.txt_failed_remove_item_localstorage);
  }
};
