const JSONAxioPost = (action, params, token) => {
  console.log('URL ', action);
  console.log('BODY ', params);
  console.log('token ', token);

  const param = JSON.stringify(params);
  var customConfig = {
    headers: {
    'Content-Type': 'application/json',
    Authorization: token,
    timeout: 60000,
    }
};
return axios.post(action, param, customConfig);
};

