// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  ToastAndroid
} from 'react-native';
import { Colors } from '../../Assets/Colors';
import { getIcon } from '../../Assets/Icon';
import Toolbar from '../../Component/Toolbar';
import { Scale } from '../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../Component/Button';
import { Routers } from '../../utils/Routers';
import ItemOrder from './ItemOrder';
import AddModal from '../../Component/AddModal';
import { JSONAxioPost, JSONAxioPostFile, JSONAxioPut } from '../../utils/services/JsonService';
import { postURL } from '../../utils/services/API';
import { getData, removeData } from '../../utils/Storage';
import { Constants } from '../../utils/Constans';
import Loading from '../../Component/loading';
import PopUp from '../../Component/popUp';
import { currency } from '../../utils/General';
import Addrerss from '../SearchAddressScreen/AddAddrerss';
import { Eng } from '../../utils/String';
import { getSystemVersion } from 'react-native-device-info';
import PopUpCheckVersion from '../../Component/PopUpCheckVersion';


const ConfirmationOrderScreen = ({route, navigation }) => {

  let [sendByState, setSendByState] = useState(
    { name: "Pilih Metode Pengiriman Anda", icon: null, height: Scale(20), width: Scale(20) });

  let [paymentMethode, setPaymentMethode] = useState(
    { name: "Pilih Metode Pembayaran", icon: null, category: null, height: Scale(20), width: Scale(50) });

  let [voucher, setVoucher] = useState(
    [
      {nama_voucher : 'Pilih Voucher', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)}]
    );
  
    let [addres, setAddress] = useState(
      {name : 'Kota Tangerang', desc: 'Jl Mushola alihsan RT 02 RW 03 Pakulonan Serpong Utara Tangerang Selatan Banten'});
    
    let [focoPoint, setFocoPoint] = useState(false)
    let [focoCoint, setFocoCoint] = useState(false)
    let [modalSchedule, setModalSchedule] = useState(false)
    let [focoSaldo, setFocoSaldo] = useState(false)

    let [focoPointTotal, setFocoPointTotal] = useState(false)
    let [focoCointTotal, setFocoCointTotal] = useState(false)
    let [focoSaldoTotal, setFocoSaldoTotal] = useState(false)

    let [product, setProduct] = useState([])
    let [detailBayar, setDetailBayar] = useState([]);
    let [total_harga, settotal_harga] = useState([]);
    let [loadingFull, setLoadingFull] = useState(false);
    let [warning, setWarning] = useState(false);
    let [contentWarning, setContentWarning] = useState(null);
  let [checkOutStatus, setCheckOutStatus] = useState(false);
  let [maximal_point, setMaximal_point] = useState(false);
  let [modalCheckVersion, setModalCheckVersion] = useState(false);
  let [contentCheckVersion, setContentCheckVersion] = useState(null);
    
    
    useEffect(() => {

      if (route.params?.sendBy) {
        setSendByState(route.params?.sendBy);
        setCheckOutStatus(true);
      }

      if (route.params?.paymentMethode) {
        setPaymentMethode(route.params?.paymentMethode);
        setCheckOutStatus(true);
      }

      if (route.params?.voucher) {
        setVoucher(route.params?.voucher);
        setCheckOutStatus(true);
      }

      if (route.params?.address) {
        setAddress(route.params?.address);
      }

      if (route.params?.dataResult){
        var data = route.params?.dataResult
        // setFocoSaldo(data?.flagMetodeBayar);
        product = [];
        setVoucher(route.params?.voucher ? route.params?.voucher : [{nama_voucher : 'Pilih Voucher', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)}]);
        setAddress(data?.alamat_kirim);
        setFocoSaldo(data?.flagSaldo);
        setFocoCoint(data?.flagCoin);
        setFocoPoint(data?.flagPoin);
        setFocoPointTotal(data?.focoPoint)
        setFocoCointTotal(data?.focoCoint)
        setFocoSaldoTotal(data?.focosaldo)
        setProduct(data?.product)
        setDetailBayar(data?.detail_bayar)
        settotal_harga(data?.total_harga)
        setMaximal_point(data?.maximal_point)

        
        // var dataResult = {
        //   voucher : route.params?.voucher ? route.params?.voucher : [{nama_voucher : 'Pilih Voucher', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)}],
        //   addres : data?.alamat_kirim,
        //   focoSaldo : data?.flagSaldo,
        //   focoCoint : data?.flagCoin,
        //   focoPoint : data?.flagPoin,
        //   focoPointTotal:data?.focosaldo,
        //   focoCointTotal: data?.focoCoint,
        //   focoSaldoTotal: data?.focoPoint,
        //   focoPointTotal: data?.focoPoint,
        //   product: data?.product,
        //   detailBayar : data?.detail_bayar,
        //   total_harga : data?.total_harga
        // }

        // setDataResult(dataResult);
      }
    }, [route.params]);

    useEffect(() => { 

      if (checkOutStatus){
        checkOut();
      }
      

    }, [checkOutStatus])

    

  const openSendBy =()=>{
    navigation.navigate(Routers.METODE_SEND, {})
  }

  const openPaymentMethode =()=>{
    navigation.navigate(Routers.PAYMENT_METODE, {})
  }

  const openVoucher =()=>{
    navigation.navigate( Routers.VOUCHER_SCREEN, {dataVoucher : voucher})
  }

  const openAddress =()=>{
    navigation.navigate( Routers.SEARCH_ADDRESS_SCREEN, {})
  }
  

  const goBack =(item)=>{
    navigation.navigate(Routers.MAIN_PAGE, {})
  }

  const useSaldo =(item)=>{
    if (focoSaldoTotal > 0){
      setFocoSaldo(!focoSaldo);
      setCheckOutStatus(true);
    } else {
      cekError(3, "Saldo Anda Tidak mencukupi")
    }
  }

  const usePoint =(item)=>{
    if (focoPointTotal > 0) {
      setFocoPoint(!focoPoint);
      setCheckOutStatus(true);
    } else {
      cekError(3, "Point Anda Tidak mencukupi")
    }
    
  }

  const useCoint =(item)=>{
    if (focoCointTotal > 0) {
      setFocoCoint(!focoCoint);
      setCheckOutStatus(true);
    } else {
      cekError(3, "Koin Anda Tidak mencukupi")
    }
    
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
        setContentWarning({
          title: "Oooops !!",
          desc: errorMessage,
          titleButton: "Login Kembali",
          statusCode: statusCode
        })
    }
    else {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }
  
  const actionButton = (statusCode) => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
        });
      });
    } 
    
  }

  const payment =()=>{
    var error = false;
    if (sendByState.name === "Pilih Metode Pengiriman Anda" && paymentMethode.name === "Pilih Metode Pembayaran" && !addres?.nama_penerima) {
      error = true;
      cekError(3, "Silakan Pilih Metode Pengiriman, Metode Pembayaran, Alamat Kirim")
    } else if (sendByState.name === "Pilih Metode Pengiriman Anda") {
      error = true;
      cekError(3, "Silakan Pilih Metode Pengiriman")
    } else if (paymentMethode.name === "Pilih Metode Pembayaran" && total_harga != 0) {
      error = true;
      cekError(3, "Silakan Pilih Metode Pembayaran")
    }else if (!addres?.nama_penerima) {
      error = true;
      cekError(3, "Silakan Pilih Alamat Kirim")
    }

    if (!error){
      hitPayment();
    }

  }


  const hitPayment =()=>{

  
    var products= []
  
    product.map((item, i) => {
        var itemProduct = {
       "id_item_produk" : item.id_item_produk,
        "totalPesanan" : item.qty_pesan}
        products.push(itemProduct);
    })
  
    let systemVersion = getSystemVersion();
    var param = {
      "alamat_kirim": addres.idalamat,
      "delivery_code": sendByState?.delivery_code ? sendByState?.delivery_code : null,
      "kode_bayar": paymentMethode?.payment_code ? paymentMethode?.payment_code : null,
      "os_version": "android_"+systemVersion,
      "version": Eng.VERSION
  }
  
  setLoadingFull(true);
  
  getData(Constants.SESSION_USER_PROFILE).then(res => {
    JSONAxioPost(postURL('api-cproses-checkout', null), param, res.result.token)
    .then(respone => {
      const response = respone?.data;
      
      console.log(JSON.stringify(response))
      setLoadingFull(false);
      if (response?.statusCode == 1) {
        if (Eng.VERSION !== response.version ){
          setModalCheckVersion(true)
          setContentCheckVersion(response)
        } else {
          console.log("Respon IF 1")
          if(total_harga > 0) {
            console.log("Respon IF 2")
            navigation.navigate(Routers.PAYMENT_GATEWAY_SCREEN, { result : response?.result, paymentMethode: response?.result?.metode_bayar_icon, transaction:true});
          } else {
            console.log("Respon else 1")
            navigation.navigate(Routers.SUCCESS_SCREEN, { paymentMethode : "Menggunakan Saldo"});
          }
          // navigation.navigate(Routers.SUCCESS_SCREEN, { paymentMethode : paymentMethode, noVa: 'xxx xxx xxxx xxxx'});  
        }
       
      } else {
        console.log("Respon else 2")
        setLoadingFull(false);

        if (Eng.VERSION !== response.version ){
          setModalCheckVersion(true)
          setContentCheckVersion(response)
        } else {
        cekError(response.statusCode,  response.message);
        }

      }
    })
    .catch(error => {
      setLoadingFull(false);
      // cekError(2,  null);

    });

  });
  }

  const checkOut =()=>{

  setLoadingFull(true)
    var products= []
  
    product.map((item, i) => {
        var itemProduct = {
       "id_item_produk" : item.id_item_produk,
        "totalPesanan" : item.qty_pesan}
        products.push(itemProduct);
    })

    var paramVoucher = voucher;

    if (paramVoucher[0]?.nama_voucher != 'Pilih Voucher') {
      paramVoucher.map((item, i) => {
        delete item.desc_long;
        delete item.is_aktif;
        delete item.ket_voucher;
        delete item.url_logo;
      })
    }
   
  
    var param = {
      "product": products,
      "flagSaldo": focoSaldo,
      "flagPoin": focoPoint,
      "flagCoin": focoCoint ? focoCoint : false,
      "metodeKirim": sendByState?.delivery_code ? sendByState?.delivery_code : null, 
      "metodeBayar": paymentMethode?.payment_code ? paymentMethode?.payment_code : null,
      "metodeVoucher":paramVoucher[0]?.nama_voucher === 'Pilih Voucher' ? null : paramVoucher
    }
  
    console.log(param);

  getData(Constants.SESSION_USER_PROFILE).then(res => {
    JSONAxioPut(postURL('api-cart-to-checkout', null), param, res.result.token)
    .then(respone => {
      const response = respone?.data;

     
      console.log("<<<<<data>>>>> ssss")
      console.log(JSON.stringify(respone?.data))
       
      if (response?.statusCode == 1) {
        console.log(response)
        product = []
        setVoucher(respone?.data?.result?.metodeVoucher.length>0 ? respone?.data?.result?.metodeVoucher : [{nama_voucher : 'Pilih Voucher', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20)}]);
        setFocoSaldo(response?.result?.flagSaldo);
        setFocoCoint(response?.result?.flagCoin);
        setFocoPoint(response?.result?.flagPoin);
        setFocoPointTotal(response?.result?.focoPoint)
        setFocoCointTotal(response?.result?.focoCoint)
        setFocoSaldoTotal(response?.result?.focosaldo)
        setDetailBayar(response?.result?.detail_bayar)
        settotal_harga(response?.result?.total_harga)
        setMaximal_point(response?.result?.maximal_point)
        setProduct(response?.result?.product)


      } else {
        cekError(response.statusCode,  response.message);
      }
      setLoadingFull(false);
      setCheckOutStatus(false)
    })
    .catch(error => {
      
      cekError(2,  null);

    });

  });
  }
  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
        onPress={goBack}
        title={'Konfirmasi Pemesanan'} />

        <ScrollView>
          <View style={{ flex: 1 }}>

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Alamat Pengiriman"}  {<FontAwesome
                    name={'map-marker-alt'}
                    size={15}
                    color={Colors.primaryColor}
                  />}</Text>
                </View>
                <View style={{ flex: 0.2 }}>
                  <TouchableOpacity
                  onPress={openAddress}>
                  <Text style={{ color: Colors.grayIcon, fontWeight: '600' }}>{"Ubah"}</Text>
                  </TouchableOpacity>
                </View>

              </View>

              <View style={{ paddingVertical: Scale(16) }}>
                <Text style={{ color: Colors.black, fontWeight: '300' }}>{(addres?.nama_penerima) ?( addres?.nama_penerima+" | "+addres?.handphone + " " + addres?.address) : "Silakan pilih alamat pengirim"}</Text>
              </View>

            </View>

           {product.length > 0 && product.map((item, i) => (
            <ItemOrder
            data={item}
            onPress={() => console.log("Other date")}/>
           )) }

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 0.1 }}>
                    <Image
                      style={{ width: Scale(15), height: Scale(15) }}
                      source={getIcon('ic_change_foco_point')} />
                  </View>

                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Gunakan Saldo"}</Text>
                  </View>
                  <View style={{ flex: 0.2 }}>
                    <TouchableOpacity
                      onPress={() => {useSaldo()}}>
                      <Image
                        style={{ width: Scale(50), height: Scale(20) }}
                        source={getIcon(focoSaldo ? 'ic_toogle_on' : 'ic_toogle_off')}
                        resizeMode='contain' />
                    </TouchableOpacity>
                  </View>
                </View>

                <Text style={{ color: Colors.black, fontWeight: '200', marginTop: Scale(3) }}>{"Sisa Saldo Anda"} {<Text style={{ color: Colors.red, fontWeight: '200', marginTop: Scale(3) }}>{"Rp " + currency(focoSaldoTotal,"")}</Text>}</Text>
              </View>
            </View>

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 0.1 }}>
                    <Image
                      style={{ width: Scale(15), height: Scale(15) }}
                      source={getIcon('ic_change_foco_point')} />
                  </View>

                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Gunakan " + maximal_point + " Foco Point"}</Text>
                  </View>
                  <View style={{ flex: 0.2 }}>
                    <TouchableOpacity
                      onPress={() => {usePoint()}}>
                      <Image
                        style={{ width: Scale(50), height: Scale(20) }}
                        source={getIcon(focoPoint ? 'ic_toogle_on' : 'ic_toogle_off')}
                        resizeMode='contain' />
                    </TouchableOpacity>
                  </View>
                </View>

                <Text style={{ color: Colors.black, fontWeight: '200', marginTop: Scale(3) }}>{"Sisa Foco Point Anda"} {<Text style={{ color: Colors.red, fontWeight: '200', marginTop: Scale(3) }}>{currency(focoPointTotal, "") + " FP"}</Text>}</Text>
              </View>
            </View>

            {/* <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 0.1 }}>
                    <Image
                      style={{ width: Scale(15), height: Scale(15) }}
                      source={getIcon('ic_change_foco_coint')}
                      resizeMode='contain' />
                  </View>

                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Gunakan 5.000 Foco Coin"}</Text>
                  </View>
                  <View style={{ flex: 0.2 }}>
                    <TouchableOpacity
                    onPress={()=> {useCoint()}}>
                      <Image
                        style={{ width: Scale(50), height: Scale(20) }}
                        source={getIcon(focoCoint ? 'ic_toogle_on' : 'ic_toogle_off')}
                        resizeMode='contain' />
                    </TouchableOpacity>
                  </View>
                </View>

                <Text style={{ color: Colors.black, fontWeight: '200', marginTop: Scale(3) }}>{"Sisa Foco Coin Anda"} {<Text style={{ color: Colors.red, fontWeight: '200', marginTop: Scale(3) }}> {currency(focoCointTotal,"")} {" FC"}</Text>}</Text>
              </View>
            </View> */}

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <TouchableOpacity
              onPress={openSendBy}>
              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Pilihan Pengiriman"}</Text>
                  </View>
                  <View style={{ flex: 0.1 }}>
                    <Image
                      style={{ height: Scale(12), width: Scale(12), marginHorizontal: Scale(8) }}
                      source={getIcon('ic_arrow_right')}
                      resizeMode='contain' />
                  </View>
                </View>

                <View style={{ flexDirection: 'row', alignItems:'center', justifyContent:'center', marginTop: Scale(sendByState.icon ? 8 : 0), marginHorizontal: Scale(sendByState.icon ? 8 : 0) }}>
                  {sendByState.icon && <View style={{ flex: 0.2, alignItems: 'center', marginRight: Scale(8)}}>
                  <Image
                      style={{ height: sendByState.height, width: sendByState.width }}
                      source={getIcon(sendByState.icon)}
                      resizeMode='contain' />
                  </View>}
                    <View style={{ flex: 1, justifyContent:'center' }}>
                      {<Text style={{ color: Colors.black, fontWeight: '200' }}>{sendByState.name}</Text>}
                    </View>
                </View>

               
              </View>
              </TouchableOpacity>
            </View>

            {total_harga != 0 && <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
            <TouchableOpacity
            onPress={openPaymentMethode}>
              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Pilihan Pembayaran"}</Text>
                  </View>
                  <View style={{ flex: 0.1 }}>
                    <Image
                      style={{ height: Scale(12), width: Scale(12), marginHorizontal: Scale(8) }}
                      source={getIcon('ic_arrow_right')}
                      resizeMode='contain' />
                  </View>
                </View>

                <View style={{ flexDirection: 'row', alignItems:'center', justifyContent:'center', marginTop: Scale(paymentMethode?.icon ? 8 : 0), marginHorizontal: Scale(paymentMethode?.icon ? 8 : 0) }}>
                  {paymentMethode.icon && <View style={{ flex: 0.2, alignItems: 'center', marginRight: Scale(8)}}>
                  <Image
                      style={{ height: paymentMethode.height, width: paymentMethode.width }}
                      source={getIcon(paymentMethode.icon)}
                      resizeMode='contain' />
                  </View>}
                    <View style={{ flex: 1, justifyContent:'center', marginLeft: Scale( paymentMethode?.name === "Shopee" ? 16 : 0) }}>
                      {<Text style={{ color: Colors.black, fontWeight: '200' }}>{paymentMethode?.category ? (paymentMethode.category + ' ' + paymentMethode?.name) : paymentMethode?.name}</Text>}
                    </View>
                </View>

               
              </View>
              </TouchableOpacity>
            </View>}

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
            <TouchableOpacity
            onPress={openVoucher}>
              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Gunakan Voucher"}</Text>
                  </View>
                  <View style={{ flex: 0.1 }}>
                    <Image
                      style={{ height: Scale(12), width: Scale(12), marginHorizontal: Scale(8) }}
                      source={getIcon('ic_arrow_right')} 
                      resizeMode='contain'/>
                  </View>
                </View>

                <Text style={{ color: Colors.black, fontWeight: '200', marginTop: Scale(3) }}>{voucher.length > 1 ? (voucher[0]?.nama_voucher + ", "+ voucher[1]?.nama_voucher) : voucher[0]?.nama_voucher}</Text>
              </View>
              </TouchableOpacity>
            </View>

           

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <Text style={{ color: Colors.black, fontWeight: '600', marginBottom: Scale(4)  }}>{"Rincian Pembayaran"}</Text>

              {detailBayar.map((item, i) => (
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 3 }}>
                    <Text style={{ fontSize: Scale(12), color: Colors.black, fontWeight: '200' }}>{item.name}</Text>
                  </View>

                  <View style={{ flex: 1, alignItems: 'flex-end' }}>
                    <Text style={{ fontSize: Scale(12), color: Colors.black, fontWeight: '400' }}>{ item.flag !== "" ? "-Rp" : "RP"}</Text>
                  </View>

                  <View style={{ flex: 1, alignItems: 'flex-end' }}>
                    <Text style={{ fontSize: Scale(12), color: Colors.black, fontWeight: '400' }}>{currency(item.values)}</Text>
                  </View>

                </View>))}
            </View>

            <AddModal
              onCloses={() => setModalSchedule(false)}
              planScheduleSend
              ShowComment={modalSchedule}
              title={'Ubah Jadwal'} />
          </View>
        </ScrollView>
        
        <View style={{height: Scale(60), backgroundColor: Colors.white, bottom: Scale(0), justifyContent: 'center', flexDirection: 'row' }}>
          <View style={{ flex: 1, justifyContent: 'center', paddingLeft: Scale(8)}}>
            <Text style={[styles.text40012]}>{'Total Pembayaran : '} {<Text style={[styles.text40012, { alignItems: 'center', color: Colors.primaryColor }]}>{"Rp " + currency(total_harga)}</Text>}</Text>
          </View>
          <View style={{ flex: 0.5, justifyContent: 'center', alignItems: 'flex-end', paddingTop: Scale(16), paddingRight: Scale(8) }}>
            <Buttons
              onPress={() => {payment()}}
              style={{ width: Scale(60), height: Scale(30), margin: Scale(2), marginTop: Scale(0), borderRadius: Scale(4) }}
              styleTitle={{ fontSize: Scale(8) }}
              title={"Bayar"} />
          </View>

        </View>
        <Loading
          visible={loadingFull} />

        <PopUpCheckVersion
          visible={modalCheckVersion}
          onPressButton={() => { setModalCheckVersion(false) }}
          contentCheckVersion={contentCheckVersion} />
        <PopUp
          visible={warning}
          onPressButton={() => { actionButton() }}
          title={contentWarning?.title}
          desc={contentWarning?.desc}
          titleButton={contentWarning?.titleButton} />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default ConfirmationOrderScreen;